      {
        "chunk_id": "8c3fea60d5f19727",
        "quote": "Quoted lead times are working days from written order acceptance, not calendar days from a user query. The supplier operates Monday to Friday, excluding supplier holidays. The holiday calendar is not provided. Lead times are estimates, not guaranteed arrival dates. Live stock is not provided in the catalogue."
      },
      {
        "chunk_id": "9f8b4d23b1a800a9",
        "quote": "Lead-time values are estimates in working days and exclude transit time. Do not promise arrival on a specific date. No expedited delivery or substitution policy is included in these documents."
      }
    ]
  },
